// Verus‐annotated binary search that returns the largest index j ∈ [c..=f]
// such that v[j] ≤ elem, or c−1 if no such index exists.
//
// Preconditions:
//   0 ≤ c ≤ v.len() as isize
//   −1 ≤ f < v.len() as isize
// Postconditions:
//   c−1 ≤ result ≤ f
//   If result ≥ c then
//     v[result] ≤ elem  ∧
//     ¬∃ j ∈ [c..=f]. (v[j] ≤ elem ∧ j > result)
//   Else (result < c) then
//     result == c−1  ∧
//     ∀ j ∈ [c..=f]. v[j] > elem
// Termination measure: max(0, f−c+1)
#[requires(0 <= c && (c as usize) <= v.len())]
#[requires(-1 <= f && (f as usize) < v.len())]
#[ensures(c - 1 <= result && result <= f)]
#[ensures(
    let ret = result;
    if ret >= c {
        // ret is the last position ≤ elem in [c..=f]
        v[ret as usize] <= elem
        &&
        !exists(|j: usize| c <= j as isize && j as isize <= f && v[j] <= elem && (j as isize) > ret)
    } else {
        // no element ≤ elem in [c..=f], so we return c−1
        ret == c - 1
        &&
        forall(|j: usize| c <= j as isize && j as isize <= f ==> v[j] > elem)
    }
)]
#[decreases(if f >= c { (f - c + 1) as nat } else { 0 })]
fn binary_search_recursive(v: &[i32], elem: i32, c: isize, f: isize) -> isize {
    // Base case: empty interval
    if c > f {
        return c - 1;
    }
    // Compute mid avoiding overflow
    let mid: isize = c + (f - c) / 2;
    let mid_usize: usize = mid as usize;

    if v[mid_usize] <= elem {
        // Recurse on the right half [mid+1..=f]
        // Show that (mid+1, f) satisfies the preconditions:
        //   0 ≤ mid+1 ≤ v.len(),  −1 ≤ f < v.len().
        assert(0 <= mid + 1);
        assert(mid + 1 <= v.len() as isize);
        assert(-1 <= f && f < v.len() as isize);
        binary_search_recursive(v, elem, mid + 1, f)
    } else {
        // Recurse on the left half [c..=mid-1]
        // Show that (c, mid-1) satisfies the preconditions:
        //   0 ≤ c ≤ v.len(),  −1 ≤ mid-1 < v.len().
        assert(0 <= c && c <= v.len() as isize);
        assert(-1 <= mid - 1);
        assert(mid - 1 < v.len() as isize);
        binary_search_recursive(v, elem, c, mid - 1)
    }
}

